<?php
namespace Modules\Ran\Services;
use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{Purchase,PurchaseLine};use Modules\Ran\Integrations\{FinanceIntegrationService,SupplierIntegrationService};use Modules\Ran\Support\RanContext;
class PurchaseService{public function __construct(private NumberSequenceService $numbers,private InventoryService $inventory,private SupplierIntegrationService $suppliers,private FinanceIntegrationService $finance,private AuditService $audit){}
 public function create(array $data):Purchase{return DB::transaction(function()use($data){$this->suppliers->find((int)$data['supplier_contact_id']);$subtotal=collect($data['lines'])->sum(fn($l)=>(float)$l['quantity']*(float)$l['unit_cost']);$total=$subtotal-(float)($data['discount_amount']??0)+(float)($data['tax_amount']??0);$p=Purchase::create(array_merge(RanContext::scope(['location_id'=>(int)($data['location_id']??RanContext::locationId()),'store_id'=>(int)($data['store_id']??RanContext::storeId())]),['purchase_no'=>$this->numbers->next('purchase'),'supplier_invoice_no'=>$data['supplier_invoice_no']??null,'purchase_date'=>$data['purchase_date'],'supplier_contact_id'=>(int)$data['supplier_contact_id'],'status'=>'draft','subtotal'=>$subtotal,'discount_amount'=>(float)($data['discount_amount']??0),'tax_amount'=>(float)($data['tax_amount']??0),'total_amount'=>$total,'paid_amount'=>0,'balance_amount'=>$total,'notes'=>$data['notes']??null]));foreach($data['lines'] as $l){$line=PurchaseLine::create(array_merge(RanContext::scope(['location_id'=>$p->location_id,'store_id'=>$p->store_id]),$l,['purchase_id'=>$p->id,'line_total'=>(float)$l['quantity']*(float)$l['unit_cost']]));}$this->audit->record('purchase_created',$p);return $p->load('lines');});}
 public function post(Purchase $p):Purchase{return DB::transaction(function()use($p){$p=Purchase::query()->lockForUpdate()->with('lines')->findOrFail($p->id);if($p->status==='posted')return $p;foreach($p->lines as $l)$this->inventory->receive(['location_id'=>$p->location_id,'store_id'=>$p->store_id,'item_id'=>$l->item_id,'lot_no'=>$l->lot_no,'serial_no'=>$l->serial_no,'quantity'=>$l->quantity,'gross_weight'=>$l->gross_weight,'net_weight'=>$l->net_weight,'stone_weight'=>$l->stone_weight,'unit_cost'=>$l->unit_cost,'total_cost'=>$l->line_total,'sale_price'=>$l->sale_price,'received_on'=>$p->purchase_date,'source_type'=>'purchase','source_id'=>$p->id,'reference_no'=>$p->purchase_no]);$this->finance->postPurchase($p);$this->suppliers->credit((int)$p->supplier_contact_id,(float)$p->total_amount,(string)$p->purchase_date,"Ran Purchase {$p->purchase_no}");$p->update(['status'=>'posted','posted_by'=>RanContext::userId(),'posted_at'=>now()]);$this->audit->record('purchase_posted',$p);return $p;});}}
